def retention(table: Table, ref: str) -> dict[str, int | None]:
    metadata_ref = table.metadata.refs[ref]
    return {
        "max_ref_age_ms": metadata_ref.max_ref_age_ms,
        "max_snapshot_age_ms": metadata_ref.max_snapshot_age_ms,
        "min_snapshots_to_keep": metadata_ref.min_snapshots_to_keep,
    }

